n=0
for k,nm,refs,li,fu,w,zi,ve,sc,q in P:
  code='PLEK-LICH-'+k
  if c.execute("select 1 from canon where code=?",(code,)).fetchone(): continue
  fn=', '.join('FUNC-'+x for x in fu.split(';'))
  f=f"Afwijkingen: {li.replace(';',', ')}. Functie: {fn}. Waarom hier nodig: {w} Wie ziet het: {zi}. Wie verbergt het: {ve}. Scènetypes en verhaallijnen: {sc}. Rol voor de quest van Liora en Teo: {q}"
  r=refs+';'+li+';'+';'.join('FUNC-'+x for x in fu.split(';'))
  c.execute("insert into canon(categorie,onderwerp,feit,status,reden,hangt_samen_met,ronde,code,verwijst_naar,functie) values('Lichaam en vervorming',?,?,'voorlopig','Ronde 11: plaatsenkaart body horror',?,11,?,?,?)",(nm,f,r,code,r,fu));n+=1
if not c.execute("select 1 from logboek where wat like 'Ronde 11b:%'").fetchone():
  c.execute("insert into logboek(datum,wat) values('2026-10-30','Ronde 11b: plaatsenkaart body horror, 21 PLEK-LICH-plekken met afwijkingen, functies, zichtbaarheid, scènetypes en questrol.')")
c.commit();print('nieuw',n)
codes={r[0] for r in c.execute('select code from canon')}
print('ontbrekend',{x for (v,) in c.execute("select verwijst_naar from canon where ronde=11") for x in v.split(';') if x and x not in codes})
